function norm(s){
  return (s||'').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
}
function normTight(s){ return norm(s).replace(/[\s\-_.]/g,''); }

function fmtMoney(v){
  const n = Number(v)||0;
  const parts = n.toFixed(2).split('.');
  const int = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return '$' + int + '<span class="cents">.' + parts[1] + '</span>';
}

function highlight(text, query){
  if(!query) return text;
  const nText = norm(text), nQuery = norm(query);
  const i = nText.indexOf(nQuery);
  if(i<0) return text;
  return text.slice(0,i)+'<mark>'+text.slice(i,i+nQuery.length)+'</mark>'+text.slice(i+nQuery.length);
}

// Combobox factory (autocomplete)
function createCombo({input, dropdown, clearBtn, getOptions, optionRender, onSelect, onInput}){
  let activeIndex=-1, currentOpts=[];
  function open(){
    const q=input.value.trim();
    currentOpts=getOptions(q);
    if(currentOpts.length===0){
      dropdown.innerHTML = q ? '<div class="dropdown-empty">Sin coincidencias</div>' : '';
      if(!q){ dropdown.classList.remove('open'); return; }
    } else {
      dropdown.innerHTML = currentOpts.map((opt,i)=>`<div class="dropdown-item" data-index="${i}">${optionRender(opt,q)}</div>`).join('');
    }
    dropdown.classList.add('open'); activeIndex=-1;
  }
  function close(){ dropdown.classList.remove('open'); activeIndex=-1; }
  function select(idx){ if(idx<0||idx>=currentOpts.length) return; onSelect(currentOpts[idx]); close(); }
  function updateActive(){
    [...dropdown.querySelectorAll('.dropdown-item')].forEach((el,i)=>{
      el.classList.toggle('active', i===activeIndex);
      if(i===activeIndex) el.scrollIntoView({block:'nearest'});
    });
  }
  input.addEventListener('focus', open);
  input.addEventListener('input', ()=>{ open(); clearBtn.classList.toggle('visible', input.value.length>0); if(onInput) onInput(); });
  input.addEventListener('keydown',(e)=>{
    if(e.key==='ArrowDown'){ e.preventDefault(); if(!dropdown.classList.contains('open')) open(); activeIndex=Math.min(activeIndex+1,currentOpts.length-1); updateActive(); }
    else if(e.key==='ArrowUp'){ e.preventDefault(); activeIndex=Math.max(activeIndex-1,0); updateActive(); }
    else if(e.key==='Enter'){ e.preventDefault(); if(activeIndex>=0) select(activeIndex); else if(currentOpts.length===1) select(0); }
    else if(e.key==='Escape'){ close(); }
  });
  dropdown.addEventListener('mousedown',(e)=>{ const it=e.target.closest('.dropdown-item'); if(it){ e.preventDefault(); select(parseInt(it.dataset.index,10)); } });
  clearBtn.addEventListener('click',()=>{ input.value=''; clearBtn.classList.remove('visible'); input.focus(); if(onInput) onInput(); open(); });
  document.addEventListener('click',(e)=>{ if(!input.contains(e.target)&&!dropdown.contains(e.target)&&!clearBtn.contains(e.target)) close(); });
  return {open, close};
}

const rfcInput=document.getElementById('rfcInput'), rfcDropdown=document.getElementById('rfcDropdown'), rfcClear=document.getElementById('rfcClear');
const rsInput=document.getElementById('rsInput'), rsDropdown=document.getElementById('rsDropdown'), rsClear=document.getElementById('rsClear');
const numInput=document.getElementById('numInput'), numDropdown=document.getElementById('numDropdown'), numClear=document.getElementById('numClear');

const results=document.getElementById('results');
const clientBanner=document.getElementById('clientBanner');
const emptyState=document.getElementById('emptyState');
const cbName=document.getElementById('cbName'), cbNum=document.getElementById('cbNum'), cbRfc=document.getElementById('cbRfc');
const metaMuertos=document.getElementById('metaMuertos'), metaHalloween=document.getElementById('metaHalloween'),
      metaOcasion=document.getElementById('metaOcasion');

createCombo({
  input:rfcInput, dropdown:rfcDropdown, clearBtn:rfcClear,
  getOptions:(q)=>{ if(!q) return []; const nq=normTight(q);
    return CLIENTS.filter(c=>c.f && normTight(c.f).includes(nq)).sort((a,b)=>a.f.localeCompare(b.f,'es')).slice(0,50); },
  optionRender:(c,q)=>`${highlight(c.f,q)}<span class="meta">${c.r}</span>`,
  onSelect:(c)=>{ rfcInput.value=c.f; rfcClear.classList.add('visible'); evaluate(); },
  onInput:()=>evaluate()
});
createCombo({
  input:rsInput, dropdown:rsDropdown, clearBtn:rsClear,
  getOptions:(q)=>{ if(!q) return []; const nq=norm(q);
    return CLIENTS.filter(c=>c.r && norm(c.r).includes(nq)).sort((a,b)=>a.r.localeCompare(b.r,'es')).slice(0,50); },
  optionRender:(c,q)=>`${highlight(c.r,q)}<span class="meta">No. ${c.n} · RFC ${c.f}</span>`,
  onSelect:(c)=>{ rsInput.value=c.r; rsClear.classList.add('visible'); evaluate(); },
  onInput:()=>evaluate()
});
createCombo({
  input:numInput, dropdown:numDropdown, clearBtn:numClear,
  getOptions:(q)=>{ if(!q) return []; const nq=normTight(q);
    return CLIENTS.filter(c=>c.n && normTight(c.n).includes(nq)).sort((a,b)=>a.n.localeCompare(b.n,'es')).slice(0,50); },
  optionRender:(c,q)=>`${highlight(c.n,q)}<span class="meta">${c.r}</span>`,
  onSelect:(c)=>{ numInput.value=c.n; numClear.classList.add('visible'); evaluate(); },
  onInput:()=>evaluate()
});

function findByField(field, value, tight){
  const v = tight ? normTight(value) : norm(value);
  if(!v) return [];
  // exact match first
  let exact = CLIENTS.filter(c=>{
    const cv = tight ? normTight(c[field]) : norm(c[field]);
    return cv === v;
  });
  if(exact.length) return exact;
  // fallback: unique contains
  return CLIENTS.filter(c=>{
    const cv = tight ? normTight(c[field]) : norm(c[field]);
    return cv.includes(v);
  });
}

function evaluate(){
  const rfcVal = rfcInput.value.trim();
  const rsVal  = rsInput.value.trim();
  const numVal = numInput.value.trim();
  const filled = [['f',rfcVal,true], ['r',rsVal,false], ['n',numVal,true]].filter(x=>x[1].length>0);

  if(filled.length < 2){
    showMessage('Llena al menos <b>2 de los 3</b> campos para mostrar las metas del cliente.');
    return;
  }

  // Each filled field must resolve to a candidate set; intersect by client identity (número is unique key)
  let candidateSets = filled.map(([field,val,tight])=>{
    const matches = findByField(field, val, tight);
    return new Set(matches.map(c=>c.n));
  });

  // intersection of candidate número sets
  let inter = [...candidateSets[0]].filter(n => candidateSets.every(s=>s.has(n)));

  if(inter.length === 0){
    showMessage('Los datos capturados <b>no coinciden con el mismo cliente</b>. Verifica que el RFC, la razón social y/o el número correspondan al mismo cliente.');
    return;
  }
  if(inter.length > 1){
    showMessage('Hay <b>varios clientes</b> que coinciden. Agrega o ajusta un tercer dato para identificar uno solo.');
    return;
  }

  const client = CLIENTS.find(c=>c.n === inter[0]);
  showResults(client);
}

function showMessage(htmlMsg){
  emptyState.innerHTML = '<svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>' + htmlMsg;
  emptyState.style.display='block';
  results.classList.remove('visible');
}

function showResults(client){
  cbName.textContent = client.r || '—';
  cbNum.textContent  = client.n || '—';
  cbRfc.textContent  = client.f || 'No disponible';

  metaMuertos.innerHTML   = fmtMoney(client.m);
  metaHalloween.innerHTML = fmtMoney(client.h);
  metaOcasion.innerHTML   = fmtMoney(client.o);

  emptyState.style.display='none';
  results.classList.add('visible');
}
</script>
</body>
</html>
